"use client";

import * as React from "react";
import { cn } from "./utils";
import { CircleIcon } from "lucide-react";
import { RadioGroup as RadioGroupPrimitive } from "./primitive-radio-group";

function RadioGroup({
  className,
  ...props
}: React.ComponentProps<typeof RadioGroupPrimitive.Root>) {
  return (
    <RadioGroupPrimitive.Root
      data-slot="radio-group"
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

function RadioGroupItem({
  className,
  ...props
}: React.ComponentProps<typeof RadioGroupPrimitive.Item>) {
  return (
    <RadioGroupPrimitive.Item
      data-slot="radio-group-item"
      className={cn("roc-ui", className)}
      {...props}
    >
      <RadioGroupPrimitive.Indicator
        data-slot="radio-group-indicator"
        className="roc-ui"
      >
        <CircleIcon className="roc-ui" />
      </RadioGroupPrimitive.Indicator>
    </RadioGroupPrimitive.Item>
  );
}

export { RadioGroup, RadioGroupItem };

import "./radio-group.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

"use client";
// ROC primitive: one choice from several, with roving focus and native form participation.
import * as React from "react";
import { FormInput } from "./primitive-form-input";
import { composeEventHandlers, useComposedRefs } from "./primitive-utils";
import {
  ROVING_ROOT,
  handleRovingKey,
  useRovingTabStop,
  type Orientation,
} from "./primitive-roving";
import { useDirectionContext } from "./primitive-direction-context";
import { useControllableState } from "./use-controllable-state";

type Context = {
  name?: string;
  required: boolean;
  disabled: boolean;
  value: string | null;
  setValue: (value: string) => void;
  fallback: string | null;
  arrowFocus: React.RefObject<boolean>;
};
const GroupContext = React.createContext<Context | null>(null);
const ItemContext = React.createContext({ checked: false, disabled: false });
const useGroup = () => {
  const context = React.useContext(GroupContext);
  if (!context) throw new Error("RadioGroup parts must be inside RadioGroup.Root");
  return context;
};

type RootProps = Omit<React.ComponentProps<"div">, "defaultValue" | "dir"> & {
  value?: string | null;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  name?: string;
  required?: boolean;
  disabled?: boolean;
  orientation?: Orientation;
  dir?: "ltr" | "rtl";
  loop?: boolean;
};

function Root({
  value: valueProp,
  defaultValue,
  onValueChange,
  name,
  required = false,
  disabled = false,
  orientation,
  dir: dirProp,
  loop = true,
  onKeyDown,
  ref,
  ...props
}: RootProps) {
  const dir = useDirectionContext(dirProp);
  const [value, setValue] = useControllableState<string | null>(
    valueProp,
    defaultValue ?? null,
    (next) => next !== null && onValueChange?.(next),
  );
  const roving = useRovingTabStop('[role="radio"][aria-checked="true"]');
  const composed = useComposedRefs<HTMLDivElement>(ref, roving.ref);
  const arrowFocus = React.useRef(false);
  const initial = React.useRef(value);
  const latest = React.useRef(setValue);
  latest.current = setValue;
  const [form, setForm] = React.useState<HTMLFormElement | null>(null);
  React.useEffect(() => {
    setForm(roving.ref.current?.closest("form") ?? null);
  }, [roving.ref]);
  React.useEffect(() => {
    if (!form) return;
    const reset = () => latest.current(initial.current);
    form.addEventListener("reset", reset);
    return () => form.removeEventListener("reset", reset);
  }, [form]);
  return (
    <GroupContext.Provider
      value={{
        name,
        required,
        disabled,
        value,
        setValue: (next) => setValue(next),
        fallback: roving.fallback,
        arrowFocus,
      }}
    >
      <div
        role="radiogroup"
        aria-required={required}
        aria-orientation={orientation}
        data-disabled={disabled ? "" : undefined}
        dir={dir}
        {...{ [ROVING_ROOT]: "" }}
        {...props}
        ref={composed}
        onKeyDown={composeEventHandlers(onKeyDown, (event) => {
          // Arrow keys move focus, and focus checks the radio (see Item).
          arrowFocus.current = true;
          handleRovingKey(event, roving.ref.current, { orientation, dir, loop });
          arrowFocus.current = false;
        })}
      />
    </GroupContext.Provider>
  );
}

type ItemProps = Omit<React.ComponentProps<"button">, "value"> & {
  value: string;
  required?: boolean;
};

function Item({
  value,
  disabled: itemDisabled,
  required: itemRequired,
  onClick,
  onKeyDown,
  onFocus,
  ref,
  children,
  ...props
}: ItemProps) {
  const group = useGroup();
  const [button, setButton] = React.useState<HTMLButtonElement | null>(null);
  const composed = useComposedRefs<HTMLButtonElement>(ref, setButton);
  const stopped = React.useRef(false);
  const checked = group.value === value;
  const disabled = group.disabled || !!itemDisabled;
  const required = group.required || !!itemRequired;
  const inForm = button ? !!button.closest("form") : true;
  return (
    <ItemContext.Provider value={{ checked, disabled }}>
      <button
        type="button"
        role="radio"
        aria-checked={checked}
        data-state={checked ? "checked" : "unchecked"}
        data-disabled={disabled ? "" : undefined}
        data-roving-item=""
        data-roving-value={value}
        disabled={disabled}
        value={value}
        tabIndex={checked || group.fallback === value ? 0 : -1}
        {...props}
        ref={composed}
        onClick={composeEventHandlers(onClick, (event) => {
          if (!checked) group.setValue(value);
          if (inForm) {
            stopped.current = event.isPropagationStopped();
            if (!stopped.current) event.stopPropagation();
          }
        })}
        onKeyDown={composeEventHandlers(onKeyDown, (event) => {
          // Per the radio pattern, Enter does not check.
          if (event.key === "Enter") event.preventDefault();
        })}
        onFocus={composeEventHandlers(onFocus, () => {
          if (group.arrowFocus.current && !checked) button?.click();
        })}
      >
        {children}
      </button>
      {inForm && (
        <FormInput
          type="radio"
          checked={checked}
          bubbles={!stopped.current}
          name={group.name}
          value={value}
          required={required}
          disabled={disabled}
        />
      )}
    </ItemContext.Provider>
  );
}

function Indicator({
  forceMount,
  ...props
}: React.ComponentProps<"span"> & { forceMount?: boolean }) {
  const { checked, disabled } = React.useContext(ItemContext);
  if (!forceMount && !checked) return null;
  return (
    <span
      data-state={checked ? "checked" : "unchecked"}
      data-disabled={disabled ? "" : undefined}
      {...props}
    />
  );
}

export const RadioGroup = { Root, Item, Indicator };

"use client";
// ROC primitive: the hidden native checkbox that lets a custom control join a <form>.
import * as React from "react";
import { usePrevious } from "./primitive-utils";

type Props = Omit<React.ComponentProps<"input">, "checked"> & {
  checked: boolean | "indeterminate";
  /** Let the synthetic click bubble to ancestors such as a form `onChange`. */
  bubbles?: boolean;
};

export function FormInput({ checked, bubbles = true, style, ...props }: Props) {
  const ref = React.useRef<HTMLInputElement>(null);
  const previous = usePrevious(checked);
  React.useEffect(() => {
    const input = ref.current;
    const set = Object.getOwnPropertyDescriptor(
      window.HTMLInputElement.prototype,
      "checked",
    )?.set;
    if (input && set && previous !== checked) {
      input.indeterminate = checked === "indeterminate";
      set.call(input, checked === "indeterminate" ? false : checked);
      input.dispatchEvent(new Event("click", { bubbles }));
    }
  }, [previous, checked, bubbles]);
  const initial = React.useRef(checked === "indeterminate" ? false : checked);
  return (
    <input
      type="checkbox"
      aria-hidden
      defaultChecked={initial.current}
      {...props}
      tabIndex={-1}
      ref={ref}
      style={{
        ...style,
        position: "absolute",
        pointerEvents: "none",
        opacity: 0,
        margin: 0,
        transform: "translateX(-100%)",
      }}
    />
  );
}

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

"use client";
// ROC primitive: arrow-key focus movement and a single tab stop for a group of items.
// Items mark themselves with `data-roving-item`; each group marks its root `data-roving-root`.
import * as React from "react";

export type Orientation = "horizontal" | "vertical";
export const ROVING_ROOT = "data-roving-root";
export const ROVING_ITEM = "[data-roving-item]";

const INTENT: Record<string, "prev" | "next" | "first" | "last"> = {
  ArrowLeft: "prev",
  ArrowUp: "prev",
  ArrowRight: "next",
  ArrowDown: "next",
  PageUp: "first",
  Home: "first",
  PageDown: "last",
  End: "last",
};

/** Items that belong to this group (not to a nested one) and can take focus. */
export function focusableItems(root: HTMLElement) {
  return Array.from(root.querySelectorAll<HTMLElement>(ROVING_ITEM)).filter(
    (item) =>
      item.closest(`[${ROVING_ROOT}]`) === root &&
      !item.matches(":disabled, [data-disabled]"),
  );
}

/** Move focus for an arrow/Home/End key. Returns whether the key was handled. */
export function handleRovingKey(
  event: React.KeyboardEvent,
  root: HTMLElement | null,
  options: { orientation?: Orientation; dir?: "ltr" | "rtl"; loop?: boolean },
) {
  if (!root || event.metaKey || event.ctrlKey || event.altKey || event.shiftKey)
    return false;
  const current = (event.target as HTMLElement).closest<HTMLElement>(ROVING_ITEM);
  if (!current || current.closest(`[${ROVING_ROOT}]`) !== root) return false;
  const rtl = (options.dir ?? getComputedStyle(root).direction) === "rtl";
  let key = event.key;
  if (rtl && key === "ArrowLeft") key = "ArrowRight";
  else if (rtl && key === "ArrowRight") key = "ArrowLeft";
  const { orientation, loop = true } = options;
  if (orientation === "vertical" && (key === "ArrowLeft" || key === "ArrowRight"))
    return false;
  if (orientation === "horizontal" && (key === "ArrowUp" || key === "ArrowDown"))
    return false;
  const intent = INTENT[key];
  if (!intent) return false;
  event.preventDefault();
  const items = focusableItems(root);
  const index = items.indexOf(current);
  let target: HTMLElement | undefined;
  if (intent === "first") target = items[0];
  else if (intent === "last") target = items[items.length - 1];
  else {
    const step = intent === "next" ? 1 : -1;
    const next = index + step;
    target = loop
      ? items[(next + items.length) % items.length]
      : items[next];
  }
  if (target && target !== current) target.focus();
  return true;
}

/**
 * One tab stop per group: the selected item, or the first enabled item when none
 * is selected. Items read `fallback` and compare it to their `data-roving-value`.
 */
export function useRovingTabStop(selectedSelector: string) {
  const ref = React.useRef<HTMLDivElement | null>(null);
  const [fallback, setFallback] = React.useState<string | null>(null);
  React.useLayoutEffect(() => {
    const root = ref.current;
    if (!root) return;
    const items = focusableItems(root);
    const next = items.some((item) => item.matches(selectedSelector))
      ? null
      : (items[0]?.dataset.rovingValue ?? null);
    setFallback((previous) => (previous === next ? previous : next));
  });
  return { ref, fallback };
}

"use client";
// ROC primitive: the reading direction set by a DirectionProvider, with no dependencies.
import * as React from "react";

export type Dir = "ltr" | "rtl";

export const DirectionContext = React.createContext<Dir | undefined>(undefined);

/** A `dir` prop wins, then the provider; undefined means "use the CSS direction". */
export function useDirectionContext(local?: Dir): Dir | undefined {
  return local ?? React.useContext(DirectionContext);
}

"use client";
import { useState } from "react";
/** An optional owner, not a mandatory store or application provider. */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (next: T) => void] {
  const [local, setLocal] = useState(defaultValue),
    current = value === undefined ? local : value;
  return [
    current,
    (next) => {
      if (Object.is(current, next)) return;
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ];
}

@import "./ui-base.css";
.roc-ui[data-slot="radio-group"] {
  display: grid;
  gap: 14px;
}
.roc-ui[data-slot="radio-group-item"] {
  position: relative;
  display: grid;
  place-items: center;
  flex: none;
  width: 18px;
  height: 18px;
  padding: 0;
  border: 1px solid var(--roc-line, #bbb);
  border-radius: 50%;
  background: var(--roc-paper, #fff);
  cursor: pointer;
  transition: border-color var(--roc-motion-quick) var(--roc-motion-ease);
}
.roc-ui[data-slot="radio-group-item"]::before {
  content: "";
  position: absolute;
  inset: -6px;
  border-radius: 50%;
}
.roc-ui[data-slot="radio-group-item"][data-state="checked"] {
  border-color: var(--roc-accent, var(--roc-ink, #252525));
  color: var(--roc-accent, var(--roc-ink, #252525));
}
.roc-ui[data-slot="radio-group-indicator"] {
  display: grid;
  place-items: center;
}
.roc-ui[data-slot="radio-group-indicator"] > svg {
  width: 8px;
  height: 8px;
  fill: currentColor;
}
/* Micro-motion: the dot pops in with a small overshoot. */
.roc-ui[data-slot="radio-group-indicator"] > svg {
  animation: roc-radio-pop var(--roc-motion-medium) var(--roc-motion-bounce);
}
@keyframes roc-radio-pop {
  from {
    scale: 0;
    opacity: 0;
  }
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
